H.background();
const m1 = P.m1, m2 = P.m2;
const u1 = 4.0, u2 = -1.0;
const s = m1 + m2;
const v1 = ((m1 - m2) * u1 + 2 * m2 * u2) / s;
const v2 = ((m2 - m1) * u2 + 2 * m1 * u1) / s;
const KEi = 0.5 * m1 * u1 * u1 + 0.5 * m2 * u2 * u2;
const KEf = 0.5 * m1 * v1 * v1 + 0.5 * m2 * v2 * v2;
H.text("Elastic Collision (1D):  KE and p both conserved", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("v1 = ((m1-m2)u1 + 2 m2 u2)/(m1+m2),   v2 = ((m2-m1)u2 + 2 m1 u1)/(m1+m2)", 24, 52, { color: H.colors.sub, size: 13 });
const cx = 450, trackY = 240, halfW = 380;
H.line(cx - halfW, trackY + 30, cx + halfW, trackY + 30, { color: H.colors.grid, width: 2 });
const period = 6;
const ph = (t % period) / period;
const collide = 0.5;
let x1, x2, sv1, sv2;
const startSep = 230;
if (ph < collide) {
  const f = ph / collide;
  x1 = cx - startSep + u1 * 22 * f;
  x2 = cx + startSep + u2 * 22 * f;
  sv1 = u1; sv2 = u2;
} else {
  const f = (ph - collide) / (1 - collide);
  const cx1 = cx - startSep + u1 * 22 * collide;
  const cx2 = cx + startSep + u2 * 22 * collide;
  x1 = cx1 + v1 * 22 * f;
  x2 = cx2 + v2 * 22 * f;
  sv1 = v1; sv2 = v2;
}
const w1 = 30 + 9 * m1, w2 = 30 + 9 * m2;
H.rect(x1 - w1 / 2, trackY, w1, 32, { fill: H.colors.accent, stroke: H.colors.ink, width: 2, radius: 4 });
H.rect(x2 - w2 / 2, trackY, w2, 32, { fill: H.colors.violet, stroke: H.colors.ink, width: 2, radius: 4 });
H.arrow(x1, trackY + 16, x1 + sv1 * 16, trackY + 16, { color: H.colors.warn, width: 3 });
H.arrow(x2, trackY + 16, x2 + sv2 * 16, trackY + 16, { color: H.colors.warn, width: 3 });
H.text("m1 = " + m1.toFixed(1) + " kg", x1 - w1 / 2, trackY - 10, { color: H.colors.accent, size: 12 });
H.text("m2 = " + m2.toFixed(1) + " kg", x2 - w2 / 2, trackY - 10, { color: H.colors.violet, size: 12 });
const phase = ph < collide ? "BEFORE  u1=+" + u1.toFixed(1) + ", u2=" + u2.toFixed(1) : "AFTER   v1=" + v1.toFixed(2) + ", v2=" + v2.toFixed(2);
H.text(phase + " m/s", 24, 350, { color: H.colors.good, size: 14, weight: 700 });
H.text("v1 = " + v1.toFixed(2) + " m/s,   v2 = " + v2.toFixed(2) + " m/s", 24, 376, { color: H.colors.accent, size: 13 });
H.text("p:  " + (m1*u1+m2*u2).toFixed(2) + " = " + (m1*v1+m2*v2).toFixed(2) + " kg*m/s  (conserved)", 24, 400, { color: H.colors.sub, size: 13 });
H.text("KE:  " + KEi.toFixed(2) + " J  ->  " + KEf.toFixed(2) + " J  (conserved)", 24, 424, { color: H.colors.good, size: 13, weight: 700 });
